async () => {
  const catalog = await connecta.call('tracker.list_projects', {});
  if (!catalog || !Array.isArray(catalog.projects)) throw new Error('Tracker project list unavailable');
  const projects = [];
  for (const item of catalog.projects) {
    if (!item || typeof item.id !== 'string') throw new Error('Invalid tracker project');
    let cursor;
    let count = 0;
    do {
      const result = await connecta.call('tracker.search_issues', {
        project: item.id, status: 'open', label: 'bug', limit: 50,
        ...(cursor ? { cursor } : {})
      });
      if (!result || !Array.isArray(result.issues)) throw new Error('Issue search unavailable for ' + item.id);
      count += result.issues.length;
      cursor = result.nextCursor;
    } while (cursor);
    projects.push({ project: item.id, openBugs: count });
  }
  return { projects };
}

async () => {
  const listing = await connecta.call('tracker.list_projects', {});
  if (!listing || !Array.isArray(listing.projects)) throw new Error('Tracker projects unavailable');
  const projects = await Promise.all(listing.projects.map(async (p) => {
    if (!p || typeof p.id !== 'string') throw new Error('Invalid tracker project');
    const result = await connecta.call('tracker.search_issues', {
      project: p.id,
      status: 'open',
      label: 'bug',
      limit: 1
    });
    if (!result || !Number.isSafeInteger(result.total) || result.total < 0) {
      throw new Error('Invalid open-bug count for ' + p.id);
    }
    return { project: p.id, openBugs: result.total };
  }));
  return { projects };
}
